+export type RoofPlaneStepDirection = 'next' | 'previous';
+
+export function stepRoofPlaneSelection(
+  planeIds: readonly string[],
+  selectedId: string | null,
+  direction: RoofPlaneStepDirection
+): string | null {
+  if (planeIds.length === 0) return null;
+
+  const selectedIndex = selectedId === null ? -1 : planeIds.indexOf(selectedId);
+  if (selectedIndex === -1) return planeIds[0];
+
+  const offset = direction === 'next' ? 1 : -1;
+  return planeIds[(selectedIndex + offset + planeIds.length) % planeIds.length];
+}
