+'use client';
+
+import { useEffectEvent } from 'react';
+
+import { useEditModeStoreApi } from '@/features/design-drawer/contexts/edit-mode-store';
+
+import { useSceneElementEventListener } from '../engine/use-scene-element-event-listener';
+import { owns3DKeyboard } from '../logic/keyboard-ownership';
+import { stepRoofPlaneSelection } from '../logic/step-roof-plane-selection';
+
+interface UseRoofPlaneStep3DConfig {
+  planeIds: readonly string[];
+  selectedId: string | null;
+  onSelect: (planeId: string | null) => void;
+  disabled?: boolean;
+}
+
+export function useRoofPlaneStep3D({
+  planeIds,
+  selectedId,
+  onSelect,
+  disabled = false,
+}: UseRoofPlaneStep3DConfig): void {
+  const storeApi = useEditModeStoreApi();
+
+  const handleKeyDown = useEffectEvent((event: KeyboardEvent) => {
+    if (disabled || !owns3DKeyboard(storeApi.getState())) return;
+    if (event.key !== '[' && event.key !== ']') return;
+
+    const target = event.target;
+    if (
+      target instanceof HTMLInputElement ||
+      target instanceof HTMLTextAreaElement ||
+      (target instanceof HTMLElement && target.isContentEditable)
+    ) {
+      return;
+    }
+
+    event.preventDefault();
+    onSelect(stepRoofPlaneSelection(planeIds, selectedId, event.key === ']' ? 'next' : 'previous'));
+  });
+
+  useSceneElementEventListener(typeof window === 'undefined' ? null : window, 'keydown', handleKeyDown);
+}
